import type { ContentDoc, ContentNode } from "@/types/content";

/** Average adult silent-reading speed used for the "N min read" estimate. */
const WORDS_PER_MINUTE = 200;
const LIBRARY_IMAGE_SRC = /^\/api\/v1\/media\/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\/file$/i;

/** Returns the media ID only for the canonical URL generated by the media API. */
export function libraryImageIdFromSrc(src: unknown): string | null {
  if (typeof src !== "string") return null;
  return LIBRARY_IMAGE_SRC.exec(src)?.[1] ?? null;
}

/** True when a canonical library URL conflicts with an explicitly supplied mediaId. */
export function hasLibraryImageMediaIdMismatch(src: unknown, mediaId: unknown): boolean {
  const urlId = libraryImageIdFromSrc(src);
  const hasExplicitMediaId = typeof mediaId === "string" && mediaId.trim().length > 0;

  return urlId !== null && hasExplicitMediaId && urlId.toLowerCase() !== mediaId.trim().toLowerCase();
}

/** Checks whether any image in a document has conflicting canonical URL and mediaId references. */
export function hasLibraryImageReferenceMismatch(node: ContentNode): boolean {
  if (
    node.type === "image" &&
    hasLibraryImageMediaIdMismatch(node.attrs?.src, node.attrs?.mediaId)
  ) {
    return true;
  }
  return node.content?.some(hasLibraryImageReferenceMismatch) ?? false;
}

export const EMPTY_DOC: ContentDoc = { type: "doc", content: [{ type: "paragraph" }] };

/** Block-level nodes whose text should be separated by a space when flattened. */
const BLOCK_TYPES = new Set(["paragraph", "heading", "blockquote", "listItem", "codeBlock", "bulletList", "orderedList"]);

/** Plain text of a document — what search and word counts run on. */
export function extractText(node: ContentNode): string {
  if (node.type === "text") return node.text ?? "";
  if (node.type === "hardBreak") return " ";
  const inner = (node.content ?? []).map(extractText).join("");
  return BLOCK_TYPES.has(node.type) ? `${inner} ` : inner;
}

export function countWords(doc: ContentNode): number {
  const text = extractText(doc).trim();
  return text ? text.split(/\s+/).length : 0;
}

export function readingTimeMinutes(wordCount: number): number {
  return wordCount === 0 ? 0 : Math.max(1, Math.round(wordCount / WORDS_PER_MINUTE));
}

export function isDocEmpty(doc: ContentNode): boolean {
  return countWords(doc) === 0 && collectImageIds(doc).length === 0;
}

/** Media IDs referenced by images, deriving the ID from canonical library URLs when needed. */
export function collectImageIds(node: ContentNode, into: string[] = []): string[] {
  if (node.type === "image") {
    const explicitMediaId = node.attrs?.mediaId;
    const mediaId =
      typeof explicitMediaId === "string" && explicitMediaId.trim().length > 0
        ? explicitMediaId
        : libraryImageIdFromSrc(node.attrs?.src);
    if (mediaId) into.push(mediaId);
  }
  node.content?.forEach((child) => collectImageIds(child, into));
  return into;
}
